/// <summary>Ported from correctAttendance in lib/store.tsx - gated on `attendance_manage`. Posts
/// only the DELTA between what the automatic late-penalty/overtime calculation already produced
/// and what the correction implies, as a new 'adjustment' ledger entry - the original automatic
/// entries (if any) are never rewritten or deleted, only reconciled forward.</summary>

await using var transaction = await _db.Database.BeginTransactionAsync(IsolationLevel.ReadCommitted, ct);
var record = await _db.AttendanceRecords
    .FromSqlRaw("SELECT * FROM AttendanceRecords WITH (UPDLOCK, ROWLOCK, HOLDLOCK) WHERE Id = {0}", request.RecordId)
    .FirstOrDefaultAsync(ct)
    ?? throw new InvalidOperationException("سجل الحضور غير موجود.");
var auditId = $"audit-attendance-correction-{request.RequestId}";
var recorded = await _db.AuditEvents.AsNoTracking().FirstOrDefaultAsync(e => e.Id == auditId, ct);
if (recorded is not null)
{
    if (recorded.ReferenceId != request.RecordId || recorded.UserId != request.ActorUserId)
        throw new DomainException("مفتاح التصحيح مستخدم لعملية أخرى.");
    return JsonSerializer.Deserialize<AttendanceRecordDto>(recorded.NewValue!)
        ?? throw new InvalidOperationException("تعذر قراءة تأكيد التصحيح السابق.");

if (employee is not null && employee.DailyWagePiastres > 0)
{
    // Match employee cash-out's ledger lock so the resulting running balance
    // cannot be computed from a simultaneous, stale drawer withdrawal.
    await _db.EmployeeLedgerEntries
        .FromSqlRaw("SELECT * FROM EmployeeLedgerEntries WITH (UPDLOCK, ROWLOCK, HOLDLOCK) WHERE EmployeeId = {0}", record.EmployeeId)
        .Select(e => e.Id).ToListAsync(ct);
    var settings = await new SettingsQueryService(_db).GetAsync(ct);
    var dailyWage = Money.FromPiastres(employee.DailyWagePiastres);

    var oldPenalty = PayrollRules.CalculateLateDeduction(dailyWage, settings.StandardWorkdayHours, oldLateMinutes,
        settings.LateGraceMinutes, settings.MaxLatePenaltyHours, settings.LatePenaltyMultiplier).Amount;
    var newPenalty = PayrollRules.CalculateLateDeduction(dailyWage, settings.StandardWorkdayHours, request.LateMinutes,
        settings.LateGraceMinutes, settings.MaxLatePenaltyHours, settings.LatePenaltyMultiplier).Amount;
    var penaltyDelta = newPenalty.Piastres - oldPenalty.Piastres;
    if (penaltyDelta != 0)
    {
        var isCredit = penaltyDelta < 0; // a REDUCED penalty credits the employee back
        await EmployeeLedgerPoster.PostIfNewAsync(_db, $"led-correction-penalty-{request.RequestId}", record.EmployeeId, nameof(LedgerEntryType.Adjustment),
            $"تصحيح خصم تأخير حضور — {request.Reason}",
            isCredit ? Money.Zero : Money.FromPiastres(Math.Abs(penaltyDelta)),
            isCredit ? Money.FromPiastres(Math.Abs(penaltyDelta)) : Money.Zero,
            verifiedApproverName, verifiedApproverName, null, record.Id, null, null, null, ct);
    }

    var oldOvertime = PayrollRules.CalculateOvertimeAmount(dailyWage, settings.StandardWorkdayHours, oldOvertimeHours, settings.OvertimeMultiplier).Amount;
    var newOvertime = PayrollRules.CalculateOvertimeAmount(dailyWage, settings.StandardWorkdayHours, request.OvertimeHours, settings.OvertimeMultiplier).Amount;
    var overtimeDelta = newOvertime.Piastres - oldOvertime.Piastres;
    if (overtimeDelta != 0)
    {
        var isCredit = overtimeDelta > 0; // an INCREASED overtime credits the employee more
        await EmployeeLedgerPoster.PostIfNewAsync(_db, $"led-correction-overtime-{request.RequestId}", record.EmployeeId, nameof(LedgerEntryType.Adjustment),
            $"تصحيح ساعات إضافية حضور — {request.Reason}",
            isCredit ? Money.Zero : Money.FromPiastres(Math.Abs(overtimeDelta)),
            isCredit ? Money.FromPiastres(Math.Abs(overtimeDelta)) : Money.Zero,
            verifiedApproverName, verifiedApproverName, null, record.Id, null, null, null, ct);

if (overtimeHours > 0 && employee.DailyWagePiastres > 0)
{
    var overtimeResult = PayrollRules.CalculateOvertimeAmount(Money.FromPiastres(employee.DailyWagePiastres),
        settings.StandardWorkdayHours, overtimeHours, settings.OvertimeMultiplier);
    if (overtimeResult.Amount.IsPositive)
    {
        var overtimeId = $"led-overtime-auto-{request.EmployeeId}-{date:yyyy-MM-dd}";
        await EmployeeLedgerPoster.PostIfNewAsync(_db, overtimeId, request.EmployeeId, nameof(LedgerEntryType.Overtime),
            $"ساعات إضافية تلقائية من البصمة ({overtimeHours} ساعة × {overtimeResult.Rate.Piastres} قرش/ساعة × {Math.Round(settings.OvertimeMultiplier * 100)}%)",
            Money.Zero, overtimeResult.Amount, employee.Name, null, activeShiftId, null, overtimeHours, overtimeResult.Rate.Piastres, null, ct);

public static async Task<EmployeeLedgerEntryEntity?> PostIfNewAsync(
    FalahDbContext db, string id, string employeeId, string type, string description, Money debit, Money credit,
    string recordedBy, string? authorizedBy, string? shiftId, string? referenceId, double? hours,
    long? rateSnapshotPiastres, long? valueSnapshotPiastres, CancellationToken ct)
{
    if (db.EmployeeLedgerEntries.Local.Any(e => e.Id == id)
        || await db.EmployeeLedgerEntries.AsNoTracking().AnyAsync(e => e.Id == id, ct)) return null;

    var currentBalance = await GetCurrentBalanceAsync(db, employeeId, ct);
    var newBalance = currentBalance + credit - debit;
    var entity = new EmployeeLedgerEntryEntity
    {
        Id = id, EmployeeId = employeeId, Type = type, Description = description,
        DebitPiastres = debit.Piastres, CreditPiastres = credit.Piastres, BalanceAfterPiastres = newBalance.Piastres,
        RecordedBy = recordedBy, AuthorizedBy = authorizedBy, ShiftId = shiftId, ReferenceId = referenceId,
        Hours = hours, RateSnapshotPiastres = rateSnapshotPiastres, ValueSnapshotPiastres = valueSnapshotPiastres,
        CreatedAtUtc = DateTimeOffset.UtcNow,
    };
    db.EmployeeLedgerEntries.Add(entity);

/// <summary>Ported from EmployeeLedgerEntry in types.ts - append-only, no update/delete path
/// anywhere (matching the reference app, which only ever appends to this array too).</summary>
public class EmployeeLedgerEntryEntity
{
    public string Id { get; set; } = default!;
    public string EmployeeId { get; set; } = default!;
    public string Type { get; set; } = default!;
    public string Description { get; set; } = default!;
    public long DebitPiastres { get; set; }
    public long CreditPiastres { get; set; }
    public long BalanceAfterPiastres { get; set; }
    public string RecordedBy { get; set; } = default!;
    public string? AuthorizedBy { get; set; }
    public string? ShiftId { get; set; }
    public string? ReferenceId { get; set; }
    public double? Hours { get; set; }
    public long? RateSnapshotPiastres { get; set; }
    public long? ValueSnapshotPiastres { get; set; }
    public string? PayrollRunId { get; set; }
    public string? TreasuryMovementId { get; set; }
    public string? IdempotencyKey { get; set; }
    public DateTimeOffset CreatedAtUtc { get; set; }

/// <summary>Ported verbatim from normalHourlyRate - a non-positive workday-hours config
/// produces a zero rate rather than a division error/NaN.</summary>
public static Money NormalHourlyRate(Money dailyWage, int workdayHours) =>
    workdayHours <= 0 ? Money.Zero : Money.FromPiastres(dailyWage.Piastres / workdayHours);

public static OvertimeAmountResult CalculateOvertimeAmount(Money dailyWage, int workdayHours, double overtimeHours, double overtimeMultiplier)
{
    var rate = NormalHourlyRate(dailyWage, workdayHours);
    if (overtimeHours <= 0) return new OvertimeAmountResult(rate, Money.Zero);
    var amount = Money.FromPiastres((long)Math.Round(rate.Piastres * overtimeHours * overtimeMultiplier));
    return new OvertimeAmountResult(rate, amount);

entity.Phone = request.Phone.Trim();
entity.HireDate = request.HireDate;
entity.CompensationType = request.CompensationType;
entity.DailyWagePiastres = request.DailyWagePiastres;
entity.ShiftValuePiastres = request.ShiftValuePiastres;
entity.MonthlySalaryPiastres = request.MonthlySalaryPiastres;
